export type SpecialArticle = {
  id: string;
  section: string;
  category: string;
  title: string;
  dek: string;
  image?: string;
  author: string;
  publishedAt: string;
  readTime: string;
  highlights: string[];
  sections: { heading: string; body: string }[];
  keyFacts: { label: string; value: string }[];
};

const editorialDate = "September 25, 2026";

function makeArticle({
  id,
  section,
  category,
  title,
  dek,
  image,
  highlights,
  sections,
  keyFacts,
  publishedAt = editorialDate,
  readTime = "7 MIN READ",
}: Omit<SpecialArticle, "author" | "publishedAt" | "readTime"> & Partial<Pick<SpecialArticle, "publishedAt" | "readTime">>): SpecialArticle {
  return {
    id,
    section,
    category,
    title,
    dek,
    image,
    author: "Sagar Kumar",
    publishedAt,
    readTime,
    highlights,
    sections,
    keyFacts,
  };
}

